  scarf_angle_threshold?: number
  /** Scarf joint flow ratio — This factor affects the amount of material for scarf joints. */
  scarf_joint_flow_ratio?: number
  /** Scarf joint speed — (mm/s or %) — This option sets the printing speed for scarf joints. It is recommended to print scarf joints at a slow speed (less than 100 mm/s). It's also advisable to enable 'Extrusion rate smoothing' if the set speed varies significantly from the speed of the outer or inner walls. If the speed specified here is higher than the speed of the outer or inner walls, the printer will default to the slower of the two speeds. When specified as a percentage (e.g., 80%), the speed is calculated based on the respective outer or inner wall speed. The default value is set to 100%. */
  scarf_joint_speed?: number | string
  /** Conditional overhang threshold — (%) — This option determines the overhang threshold for the application of scarf joint seams. If the unsupported portion of the perimeter is less than this threshold, scarf joint seams will be applied. The default threshold is set at 40% of the external wall's width. Due to performance considerations, the degree of overhang is estimated. */
  scarf_overhang_threshold?: number
  /** Seam gap — (mm or %) — In order to reduce the visibility of the seam in a closed loop extrusion, the loop is interrupted and shortened by a specified amount. This amount can be specified in millimeters or as a percentage of the current extruder diameter. The default value for this parameter is 10%. */
