  support_angle?: number
  support_base_diameter?: number
  support_base_height?: number
  /** Base pattern — Line pattern of support. The Default option for Tree supports is Hollow, which means no base pattern. For other support types, the Default option is the Rectilinear pattern. NOTE: For Organic supports, the two walls are supported only with the Hollow/Default base pattern. The Lightning base pattern is supported only by Tree Slim/Strong/Hybrid supports. For the other support types, the Rectilinear will be used instead of Lightning. */
  support_base_pattern?: 'default' | 'rectilinear' | 'rectilinear-grid' | 'honeycomb' | 'lightning' | 'hollow'
  /** Base pattern spacing — (mm) — This determines the spacing between support lines. */
  support_base_pattern_spacing?: number
  support_base_safety_distance?: number
  /** Bottom interface spacing — (mm) — This is the spacing of bottom interface lines. 0 means solid interface. */
